// ── Governed AI workforce ───────────────────────────────────────────────────
// Agents are versioned definitions that run with an explicit identity: the requesting person, or a restricted
// service identity. They can only call tools on their allowlist, each tool checks the identity's own permissions,
// and every consequential tool call becomes a pending approval that a person reviews (and executes with THEIR
// permissions). Kill switches, budgets, step limits and evaluations bound what an agent can do.
export type AgentDef={purpose:string,instructions:string,pages:string[],recordScope:'own'|'department'|'all',serviceDepartment?:string,runAs:'requester'|'service',tools:string[],connectors:string[],knowledge:{search:boolean,graph:boolean,files:boolean,connectors:boolean},provider:'default',model?:string,temperature:number,maxSteps:number,tokenBudget:number,costBudgetMicros:number,schedule:'none'|'daily'|'weekly',scheduledPrompt?:string,triggers:{module?:string,action?:string,prompt:string}[],extraApprovals:string[],retentionDays:number,roles:string[]};
export const defaultDef=():AgentDef=>({purpose:'',instructions:'',pages:[],recordScope:'department',runAs:'requester',tools:['search_knowledge','read_record','graph_context'],connectors:[],knowledge:{search:true,graph:true,files:true,connectors:false},provider:'default',temperature:0.2,maxSteps:6,tokenBudget:200000,costBudgetMicros:0,schedule:'none',triggers:[],extraApprovals:[],retentionDays:90,roles:[]});
const T=(name:string,description:string,pages:string[],tools:string[],instructions:string,runAs:AgentDef['runAs']='requester'):{id:string,name:string,description:string,def:Partial<AgentDef>}=>({id:name.toLowerCase().replace(/[^a-z]+/g,'-').replace(/-$/,''),name,description,def:{purpose:description,instructions,pages,tools,runAs}});
